mapper.select:
-- ============================================== -- 功能：未来3天生产订单【订单级汇总查询】物料齐套性 -- 核心业务规则：①当日订单仅抢占当日库存，跨日期无抢占 ②订单号小优先占用库存，同单号按主料号排序 ③后天库存计算需扣减未结出库量 ④木桶效应判定整单齐套性 -- ============================================== WITH -- 基础数据：物料BOM清单，按主料+组件维度汇总单台用量 COMMON_BOM AS ( SELECT MAIN_MATERIAL_NO, COMPONENT_MATERIAL_NO, COMPONENT_DESC, SUM(UNIT_USAGE) AS UNIT_USAGE FROM RUOYI.MATERIAL_BOM_IMPORT WHERE DELETED = 0 AND LEVEL_NO = 1 GROUP BY MAIN_MATERIAL_NO, COMPONENT_MATERIAL_NO, COMPONENT_DESC ), -- 基础数据：物料实时库存，按物料号汇总可用库存总量 COMMON_STOCK AS ( SELECT MATERIAL_NO, SUM(AVAILABLE_QUANTITY) AS AVAILABLE_QUANTITY FROM RUOYI.REAL_TIME_STOCK WHERE DELETED = 0 OR DELETED IS NULL GROUP BY MATERIAL_NO ), -- 基础数据：订单未结出库量，按订单+物料维度汇总待出库数量 COMMON_TRACE AS ( SELECT ORDER_NO, MATERIAL_NO, SUM(OUTBOUND_ACCUMULATED) AS OPEN_QUANTITY FROM RUOYI.TRACE_ORDER_DEMAND WHERE DELETED = 0 GROUP BY ORDER_NO, MATERIAL_NO ), -- 基础数据：工单已出库量，按订单+物料维度汇总已领用数量 COMMON_TASK AS ( SELECT order_no, material_no, SUM(quantity) AS outbound_qty FROM RUOYI.WM_DISTRIBUTION_TASK WHERE deleted = 0 GROUP BY order_no, material_no ), -- 库存占用量汇总 - 订单优先级递进扣减逻辑 STOCK_OCCUPY_SUM AS ( SELECT mp2.PRODUCTION_ORDER_NO, mp2.ASSEMBLY_MATERIAL_NO, bom2.COMPONENT_MATERIAL_NO, mp2.SCHEDULED_DATE, SUM( LEAST( CASE WHEN mp2.SCHEDULED_DATE = TRUNC(SYSDATE)+2 THEN mp2.SCHEDULED_QUANTITY * bom2.UNIT_USAGE - COALESCE(TRACE2.OPEN_QUANTITY,0) ELSE mp2.SCHEDULED_QUANTITY * bom2.UNIT_USAGE END, GREATEST(0, COALESCE(stock2.AVAILABLE_QUANTITY,0) - COALESCE(TRACE2.OPEN_QUANTITY,0)) ) ) AS OCCUPY_SUM FROM RUOYI.APS_MAIN_PLAN mp2 JOIN COMMON_BOM bom2 ON mp2.ASSEMBLY_MATERIAL_NO = bom2.MAIN_MATERIAL_NO LEFT JOIN COMMON_STOCK stock2 ON bom2.COMPONENT_MATERIAL_NO = stock2.MATERIAL_NO LEFT JOIN COMMON_TRACE TRACE2 ON mp2.PRODUCTION_ORDER_NO = TRACE2.ORDER_NO AND bom2.COMPONENT_MATERIAL_NO = TRACE2.MATERIAL_NO WHERE mp2.DELETED =0 AND mp2.SCHEDULED_DATE BETWEEN TRUNC(SYSDATE)+1 AND TRUNC(SYSDATE)+3 AND EXISTS ( SELECT 1 FROM RUOYI.APS_MAIN_PLAN mp3 WHERE mp3.DELETED=0 AND mp3.SCHEDULED_DATE = mp2.SCHEDULED_DATE AND mp3.ASSEMBLY_MATERIAL_NO = mp2.ASSEMBLY_MATERIAL_NO AND (mp3.PRODUCTION_ORDER_NO < mp2.PRODUCTION_ORDER_NO OR (mp3.PRODUCTION_ORDER_NO = mp2.PRODUCTION_ORDER_NO AND mp3.ASSEMBLY_MATERIAL_NO < mp2.ASSEMBLY_MATERIAL_NO)) ) GROUP BY mp2.PRODUCTION_ORDER_NO, mp2.ASSEMBLY_MATERIAL_NO, bom2.COMPONENT_MATERIAL_NO, mp2.SCHEDULED_DATE ), -- 主数据整合：订单+物料+库存+占用量 全维度基础数据 BASE_PROD_DATA AS ( SELECT mp.PRODUCTION_ORDER_NO, mp.ASSEMBLY_MATERIAL_NO, mp.MAIN_MATERIAL_DESC, mp.SCHEDULED_DATE, mp.PRODUCTION_WORKSHOP, mp.SCHEDULED_QUANTITY, bom.COMPONENT_MATERIAL_NO, bom.COMPONENT_DESC, bom.UNIT_USAGE, NVL(mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE, 0) AS REQUIRED_QTY, NVL(stock.AVAILABLE_QUANTITY, 0) AS TOTAL_AVAILABLE_STOCK, NVL(TRACE.OPEN_QUANTITY, 0) AS OPEN_QUANTITY, NVL(task.outbound_qty, 0) AS outbound_qty, CASE WHEN mp.SCHEDULED_DATE = TRUNC(SYSDATE) + 1 THEN LEAST(mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE, GREATEST(0, COALESCE(stock.AVAILABLE_QUANTITY,0) - NVL(s.OCCUPY_SUM, 0))) ELSE 0 END AS STOCK_TOMORROW, CASE WHEN mp.SCHEDULED_DATE = TRUNC(SYSDATE) + 2 THEN LEAST((mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE) - COALESCE(TRACE.OPEN_QUANTITY,0), GREATEST(0, COALESCE(stock.AVAILABLE_QUANTITY,0) - NVL(s.OCCUPY_SUM, 0))) ELSE 0 END AS STOCK_DAY_AFTER_TOMORROW, CASE WHEN mp.SCHEDULED_DATE = TRUNC(SYSDATE) + 3 THEN LEAST(mp.SCHEDULED_QUANTITY * bom.UNIT_USAGE, GREATEST(0, COALESCE(stock.AVAILABLE_QUANTITY,0) - NVL(s.OCCUPY_SUM, 0))) ELSE 0 END AS STOCK_THIRD_DAY FROM RUOYI.APS_MAIN_PLAN mp JOIN COMMON_BOM bom ON mp.ASSEMBLY_MATERIAL_NO = bom.MAIN_MATERIAL_NO LEFT JOIN COMMON_STOCK stock ON bom.COMPONENT_MATERIAL_NO = stock.MATERIAL_NO LEFT JOIN COMMON_TRACE TRACE ON mp.PRODUCTION_ORDER_NO = TRACE.ORDER_NO AND bom.COMPONENT_MATERIAL_NO = TRACE.MATERIAL_NO LEFT JOIN COMMON_TASK task ON mp.PRODUCTION_ORDER_NO = task.order_no AND bom.COMPONENT_MATERIAL_NO = task.material_no LEFT JOIN STOCK_OCCUPY_SUM s ON mp.PRODUCTION_ORDER_NO = s.PRODUCTION_ORDER_NO AND mp.ASSEMBLY_MATERIAL_NO = s.ASSEMBLY_MATERIAL_NO AND bom.COMPONENT_MATERIAL_NO = s.COMPONENT_MATERIAL_NO AND mp.SCHEDULED_DATE = s.SCHEDULED_DATE WHERE mp.DELETED = 0 AND mp.SCHEDULED_DATE BETWEEN TRUNC(SYSDATE) + 1 AND TRUNC(SYSDATE) + 3 ), -- 组件级核心计算：计算每个组件的可配套数 COMPONENT_CORE_CALC AS ( SELECT PRODUCTION_ORDER_NO, ASSEMBLY_MATERIAL_NO, MAIN_MATERIAL_DESC, SCHEDULED_DATE, PRODUCTION_WORKSHOP, SCHEDULED_QUANTITY, NVL(UNIT_USAGE,0) AS UNIT_USAGE, NVL(REQUIRED_QTY,0) AS REQUIRED_QTY, (STOCK_TOMORROW + STOCK_DAY_AFTER_TOMORROW + STOCK_THIRD_DAY) AS STOCK_QUANTITY, OPEN_QUANTITY, -- 直接计算可配套数 CASE WHEN ((STOCK_TOMORROW + STOCK_DAY_AFTER_TOMORROW + STOCK_THIRD_DAY) + OPEN_QUANTITY) >= REQUIRED_QTY THEN SCHEDULED_QUANTITY WHEN ((STOCK_TOMORROW + STOCK_DAY_AFTER_TOMORROW + STOCK_THIRD_DAY) + OPEN_QUANTITY) > 0 THEN FLOOR(((STOCK_TOMORROW + STOCK_DAY_AFTER_TOMORROW + STOCK_THIRD_DAY) + OPEN_QUANTITY) / UNIT_USAGE) ELSE 0 END AS COMPLETABLE_SETS FROM BASE_PROD_DATA ), -- 核心逻辑【木桶效应】：订单级齐套性判定 MIN_COMPLETABLE_SETS AS ( SELECT PRODUCTION_ORDER_NO, ASSEMBLY_MATERIAL_NO, MAIN_MATERIAL_DESC, SCHEDULED_DATE, PRODUCTION_WORKSHOP, SCHEDULED_QUANTITY, MIN(COMPLETABLE_SETS) AS min_completable_sets FROM COMPONENT_CORE_CALC GROUP BY PRODUCTION_ORDER_NO, ASSEMBLY_MATERIAL_NO, MAIN_MATERIAL_DESC, SCHEDULED_DATE, PRODUCTION_WORKSHOP, SCHEDULED_QUANTITY ) -- 最终订单级汇总查询 SELECT PRODUCTION_ORDER_NO, -- 1. 生产订单号 ASSEMBLY_MATERIAL_NO, -- 2. 总成物料号 MAIN_MATERIAL_DESC, -- 3. 主物料描述 SCHEDULED_DATE, -- 4. 排产时间 -- 组件级KITTING_STATUS CASE WHEN min_completable_sets >= SCHEDULED_QUANTITY THEN '齐套' WHEN min_completable_sets > 0 THEN '齐套' || min_completable_sets || '套' ELSE '不齐套' END AS KITTING_STATUS, -- 5. 组件是否齐套 PRODUCTION_WORKSHOP, -- 6. 生产车间 SCHEDULED_QUANTITY, -- 7. 排产数量 CASE WHEN min_completable_sets >= SCHEDULED_QUANTITY THEN '齐套' WHEN min_completable_sets > 0 THEN '齐套' || min_completable_sets || '套' ELSE '不齐套' END AS ASSEMBLY_KITTING_STATUS -- 8. 订单是否齐套 FROM MIN_COMPLETABLE_SETS WHERE 1=1 -- 条件1：按生产订单号精确筛选
AND PRODUCTION_ORDER_NO = #{params.productionOrderNo}
-- 条件2：按装配物料号精确筛选
AND ASSEMBLY_MATERIAL_NO = #{params.assemblyMaterialNo}
-- 条件3：按组件物料号精确筛选
AND COMPONENT_MATERIAL_NO = #{params.componentMaterialNo}
-- 条件4：按主物料描述模糊筛选
AND MAIN_MATERIAL_DESC LIKE '%' || #{params.mainMaterialDesc} || '%'
-- 条件5：按生产车间精确筛选
AND PRODUCTION_WORKSHOP = #{params.productionWorkshop}
-- 条件6：按计划日期范围筛选（传入2个日期时）
AND SCHEDULED_DATE BETWEEN #{params.scheduledDate[0]} AND #{params.scheduledDate[1]}
-- 条件7：按计划日期精确筛选（传入1个日期时）
AND SCHEDULED_DATE = #{params.scheduledDate[0]}
-- 排序规则：优先级（齐套→齐套X件→不齐套），再按排产日期、订单号排序 ORDER BY min_completable_sets desc, SCHEDULED_DATE, PRODUCTION_ORDER_NO
